"""Largest-remainder allocation of an amount in cents. See task.md."""

from __future__ import annotations


def _check_int(value: object, name: str) -> None:
    if isinstance(value, bool) or not isinstance(value, int):
        raise ValueError(f"{name} must be an int")


def allocate(amount: int, weights: list[int]) -> list[int]:
    """Split `amount` cents in proportion to `weights`, one share per weight."""
    _check_int(amount, "amount")
    if amount < 0:
        raise ValueError("amount must not be negative")
    if len(weights) == 0:
        raise ValueError("weights must not be empty")
    for weight in weights:
        _check_int(weight, "weight")
        if weight < 0:
            raise ValueError("weights must not be negative")

    total = sum(weights)
    if total == 0:
        raise ValueError("at least one weight must be positive")

    shares = [amount * weight // total for weight in weights]
    remainders = [amount * weight % total for weight in weights]
    leftover = amount - sum(shares)

    by_remainder = sorted(range(len(weights)), key=lambda i: (-remainders[i], i))
    for i in by_remainder[:leftover]:
        shares[i] += 1
    return shares
